public static String formatSpell(String name, int power) {
    if (name == null || name.isBlank()) {
        throw new IllegalArgumentException("Spell name must not be blank");
    }
    if (power < 0 || power > 100) {
        throw new IllegalArgumentException("Power must be 0-100, got: " + power);
    }
    return String.format("%s [%d]", name.trim(), power);
}

